    private static void pool(String countries,String first,String last){String[] v={first,last};for(String c:countries.split(";"))POOLS.put(c,v);}
    public static boolean supports(String nationality){return POOLS.containsKey(nationality);}
    public static String name(String nationality,long identity) {
        String[] p=POOLS.get(nationality);
        if(p==null)p=POOLS.get("England");
        String[] first=p[0].split(" "),last=p[1].split(" ");Random r=new Random(identity^0x4E414D4553L);
        return prettify(first[r.nextInt(first.length)])+" "+prettify(last[r.nextInt(last.length)]);
    }
    private static String prettify(String s){return s.replace("deVries","de Vries").replace("deJong","de Jong").replace("deBoer","de Boer").replace("vanDijk","van Dijk").replace("vanLeeuwen","van Leeuwen").replace("vanBerg","van den Berg").replace("vanBeek","van Beek").replace("DeLuca","De Luca").replace("BenYoussef","Ben Youssef").replace("BenSalah","Ben Salah").replace("BenAmor","Ben Amor").replace("ElAmrani","El Amrani").replace("ElIdrissi","El Idrissi");}
